import{_ as t,o as a,c as r,ah as n}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse('{"title":"Le portail parent","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/parent/index.md","filePath":"src/guide/parent/index.md"}'),s={name:"guide/parent/index.md"};function d(i,e,o,u,l,p){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="le-portail-parent" tabindex="-1">Le portail parent <a class="header-anchor" href="#le-portail-parent" aria-label="Permalink to &quot;Le portail parent&quot;">​</a></h1><p>En tant que parent ou tuteur, vous disposez d&#39;un espace dédié pour suivre la scolarité de vos enfants : notes, présences, documents à télécharger, paiements et démarches. Une fois connecté, vous arrivez sur la page <strong>Mes enfants</strong>, qui affiche une carte par enfant rattaché à votre compte : sa classe, les absences à justifier, la prochaine échéance de paiement, sa moyenne, son solde et ses dernières notes. Cliquez sur une carte pour ouvrir le suivi complet de cet enfant.</p><p>Ce guide couvre les trois choses que vous pouvez faire depuis ce portail :</p><table tabindex="0"><thead><tr><th>Page</th><th>Ce que vous pouvez y faire</th></tr></thead><tbody><tr><td><a href="/era-guide/guide/parent/enfants-et-documents.html">Vos enfants et leurs documents</a></td><td>Voir vos enfants, consulter leur suivi (notes, présences, discipline) et télécharger leurs bulletins, reçus, procès-verbaux et documents du cahier de texte ; exporter leur emploi du temps</td></tr><tr><td><a href="/era-guide/guide/parent/paiements-en-ligne.html">Paiements en ligne</a></td><td>Suivre les frais de scolarité et payer directement en ligne par mobile money</td></tr><tr><td><a href="/era-guide/guide/parent/demarches.html">Démarches</a></td><td>Justifier l&#39;absence d&#39;un enfant ou demander un transfert de site</td></tr></tbody></table><h2 id="ce-dont-vous-etes-prevenu" tabindex="-1">Ce dont vous êtes prévenu <a class="header-anchor" href="#ce-dont-vous-etes-prevenu" aria-label="Permalink to &quot;Ce dont vous êtes prévenu&quot;">​</a></h2><p>L&#39;établissement vous prévient, par e-mail et dans la cloche de notifications de votre espace, dans ces cas :</p><table tabindex="0"><thead><tr><th>Vous êtes prévenu quand…</th><th>Ce que vous y trouvez</th></tr></thead><tbody><tr><td>le bulletin d&#39;une période est publié</td><td>le lien vers la fiche de votre enfant</td></tr><tr><td>votre enfant est noté absent sans justification</td><td>la date et la classe, pour justifier</td></tr><tr><td>votre justificatif d&#39;absence est accepté ou refusé</td><td>la décision, et le motif d&#39;un refus</td></tr><tr><td>un incident disciplinaire est enregistré</td><td>la date et la gravité</td></tr><tr><td>un conseil de discipline est convoqué, puis quand il a décidé</td><td>la date de la séance, puis la décision</td></tr><tr><td>votre enfant est renvoyé à la maison par l&#39;infirmerie</td><td>le motif et l&#39;heure du passage</td></tr><tr><td>un paiement est enregistré</td><td>le montant et le solde restant</td></tr></tbody></table><p>Vous n&#39;êtes pas prévenu de chaque note : les notes de la période se découvrent avec le bulletin, et les moyennes restent consultables à tout moment sur la fiche de votre enfant.</p><p>Les réglages de votre compte (mot de passe, notifications, langue) sont les mêmes pour tous les rôles : voir <a href="/era-guide/guide/prise-en-main.html">Bien démarrer</a>.</p>',9)])])}const h=t(s,[["render",d]]);export{m as __pageData,h as default};
